import SwiftUI
import AtiCleanerCore

struct OverviewView: View {
    @State private var disk=DiskService.snapshot(); @State private var memory=MemoryService.snapshot()
    var body: some View {ScrollView{VStack(alignment:.leading,spacing:24){PageHeader(icon:"gauge",title:"Ati Cleaner",subtitle:"Mac'inizi güvenli şekilde analiz edin, alan kazanın ve gereksiz dosyaları yönetin.",tint:Theme.accent);HStack(spacing:24){if let disk{ZStack{Circle().stroke(Color.secondary.opacity(0.14),lineWidth:18);Circle().trim(from:0,to:disk.usedFraction).stroke(Theme.accent,style:StrokeStyle(lineWidth:18,lineCap:.round)).rotationEffect(.degrees(-90));VStack{Text("Disk").font(.headline);Text(Int64(disk.available).formattedBytes).font(.title2.bold());Text("boş").foregroundStyle(.secondary)}}.frame(width:190,height:190);VStack(alignment:.leading,spacing:10){Text("Depolama").font(.title2.bold());Text("Toplam: \(disk.total.formattedBytes)");Text("Kullanılan: \(disk.used.formattedBytes)");Text("Boş: \(disk.available.formattedBytes)")}.frame(maxWidth:.infinity,alignment:.leading)};if let memory{VStack(alignment:.leading,spacing:10){Text("Bellek").font(.title2.bold());Text("Toplam: \(Int64(memory.total).formattedBytes)");Text("Kullanılan: \(Int64(memory.used).formattedBytes)");Text("Boş: \(Int64(memory.free).formattedBytes)")}.frame(maxWidth:.infinity,alignment:.leading)}}.padding(20).background(RoundedRectangle(cornerRadius:16).fill(Color(nsColor:.controlBackgroundColor)))}}.padding(24)}}
